package com.neurosql.api; import static org.assertj.core.api.Assertions.assertThat; import java.util.Map; import org.junit.jupiter.api.Test; class HealthControllerTest { @Test void healthReportsServiceStatus(){Map<String,Object> result=new HealthController().health();assertThat(result).containsEntry("status","UP");assertThat(result).containsEntry("service","neurosql-api");assertThat(result).containsKey("timestamp");} }